local colors = require('colors')-- ========================================-- Reset-- ========================================vim.cmd('highlight clear')vim.cmd('syntax reset')vim.g.colors_name = 'custom'-- ========================================-- Helper-- ========================================local function set(name, opts)  vim.api.nvim_set_hl(0, name, opts)end-- ========================================-- Editor-- ========================================set('Normal', {  fg = colors.fg,  bg = colors.bg,})set('NormalNC', {  fg = colors.fg,  bg = colors.bg,})set('EndOfBuffer', {  fg = colors.bg,  bg = colors.bg,})set('SignColumn', {  bg = colors.bg,})set('FoldColumn', {  bg = colors.bg,})set('LineNr', {  fg = colors.fg_muted,  bg = colors.bg,})set('CursorLineNr', {  fg = colors.fg_bright,  bg = colors.bg,})set('CursorLine', {  bg = colors.bg_light,})set('Visual', {  bg = colors.selection,})set('Cursor', {  fg = colors.bg,  bg = colors.cursor,})-- ========================================-- Window-- ========================================set('WinSeparator', {  fg = colors.border,  bg = colors.bg,})set('VertSplit', {  fg = colors.border,  bg = colors.bg,})-- ========================================-- Floating Window-- ========================================set('NormalFloat', {  fg = colors.fg,  bg = colors.bg,})set('FloatBorder', {  fg = colors.border,  bg = colors.bg,})-- ========================================-- Syntax-- ========================================set('Comment', {  fg = colors.comment,})set('String', {  fg = colors.string,})set('Number', {  fg = colors.number,})set('Constant', {  fg = colors.constant,})set('Keyword', {  fg = colors.keyword,})set('Type', {  fg = colors.class,})set('Function', {  fg = colors.method,})set('Operator', {  fg = colors.operator,})set('Identifier', {  fg = colors.fg,})set('csRepeat', {  bold = false,})set('Statement', {  bold = false,})set('DiagnosticUnnecessary', {  fg = colors.unnecessary,})-- ========================================-- C# LSP Semantic Tokens-- ========================================set('@lsp.type.method.cs', {  fg = colors.method,})set('@lsp.type.extensionMethod.cs', {  fg = colors.method,  italic = true,})set('@lsp.type.class.cs', {  fg = colors.class,})set('@lsp.type.struct.cs', {  fg = colors.struct,})set('@lsp.type.field.cs', {  fg = colors.field,})set('@lsp.type.property.cs', {  fg = colors.property,})set('@lsp.type.keyword.cs', {  fg = colors.keyword,})set('@lsp.type.controlKeyword.cs', {  fg = colors.control_keyword,  bold = false,})set('@lsp.type.parameter.cs', {  fg = colors.parameter,  italic = true,})set('@lsp.type.namespace.cs', {  fg = colors.namespace,})-- ========================================-- Diagnostics-- ========================================set('DiagnosticError', {  fg = colors.error,})set('DiagnosticWarn', {  fg = colors.warning,})set('DiagnosticInfo', {  fg = colors.info,})set('DiagnosticHint', {  fg = colors.hint,})set('DiagnosticVirtualTextError', {  fg = colors.error,})set('DiagnosticVirtualTextWarn', {  fg = colors.warning,})set('DiagnosticVirtualTextInfo', {  fg = colors.info,})set('DiagnosticVirtualTextHint', {  fg = colors.hint,})-- ========================================-- Search-- ========================================set('Search', {  fg = colors.fg_bright,  bg = colors.selection,})set('IncSearch', {  fg = colors.bg,  bg = colors.keyword,})set('CurSearch', {  fg = colors.bg,  bg = colors.keyword,})-- ========================================-- Pmenu / Completion-- ========================================set('Pmenu', {  fg = colors.fg,  bg = colors.bg_light,})set('PmenuSel', {  fg = colors.fg_bright,  bg = colors.selection,})set('PmenuSbar', {  bg = colors.bg_light,})set('PmenuThumb', {  bg = colors.border,})-- ========================================-- Status / Tabline-- ========================================set('StatusLine', {  fg = colors.fg,  bg = colors.bg_light,})set('StatusLineNC', {  fg = colors.fg_muted,  bg = colors.bg,})set('TabLine', {  fg = colors.fg_muted,  bg = colors.bg,})set('TabLineFill', {  bg = colors.bg,})set('TabLineSel', {  fg = colors.fg_bright,  bg = colors.selection,})-- ========================================-- Git Signs-- ========================================set('GitSignsAdd', {  fg = colors.git_add,})set('GitSignsChange', {  fg = colors.git_change,})set('GitSignsDelete', {  fg = colors.git_delete,})